import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.BQh0MzVE.js";var i=JSON.parse(`{"title":"Environment Variables","description":"","frontmatter":{},"headers":[],"relativePath":"pages/config/env_vars.md","filePath":"pages/config/env_vars.md"}`),a={name:`pages/config/env_vars.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment Variables”">​</a></h1><p>Here is a list of available environment variables that can be used to configure SQL Exporter:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Environment Variable</th><th>Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SQLEXPORTER_CONFIG</code></td><td><code>sql_exporter.yml</code></td><td style="text-align:left;">file path to the configuration file</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_COLLECTOR_FILES</code></td><td></td><td style="text-align:left;">glob pattern(s) for collector definition files, semicolon-separated</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Environment Variable</th><th>Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_MIN_INTERVAL</code></td><td><code>0s</code></td><td style="text-align:left;">minimum interval between query executions</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_SCRAPE_TIMEOUT</code></td><td><code>10s</code></td><td style="text-align:left;">per-scrape timeout, global</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_SCRAPE_TIMEOUT_OFFSET</code></td><td><code>500ms</code></td><td style="text-align:left;">offset to subtract from timeout in seconds</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_SCRAPE_ERROR_DROP_INTERVAL</code></td><td><code>0s</code></td><td style="text-align:left;">interval to drop scrape errors from the error counter</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_PING_INTERVAL</code></td><td><code>0s</code></td><td style="text-align:left;">interval between database pings</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_MAX_CONNECTIONS</code></td><td><code>3</code></td><td style="text-align:left;">maximum number of open connections to any one target</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_MAX_IDLE_CONNECTIONS</code></td><td><code>3</code></td><td style="text-align:left;">maximum number of idle connections to any one target</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_MAX_CONNECTION_LIFETIME</code></td><td><code>0</code></td><td style="text-align:left;">maximum amount of time a connection may be reused to any one target</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_WARMUP_DELAY</code></td><td><code>0s</code></td><td style="text-align:left;">delay between executing collectors during cache population at startup</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_GLOBAL_ENABLE_QUERY_METRICS</code></td><td><code>false</code></td><td style="text-align:left;">expose per-query duration and row count metrics</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Environment Variable</th><th>Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SQLEXPORTER_TARGET_NAME</code></td><td></td><td style="text-align:left;">(Optional) Target name, generates <code>up</code> and <code>scrape_duration_seconds</code> additional metrics)</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_TARGET_DSN</code></td><td></td><td style="text-align:left;">URL-format connection string for the target database</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_TARGET_COLLECTORS</code></td><td></td><td style="text-align:left;">Collector names to execute on the target, should be semicolon-separated</td></tr><tr><td style="text-align:left;"><code>SQLEXPORTER_TARGET_ENABLE_PING</code></td><td><code>true</code></td><td style="text-align:left;">ping the database before executing collectors</td></tr></tbody></table>`,5)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};